import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ref, push } from 'firebase/database';
import { database } from '../firebase';

const SearchSeries = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!searchTerm.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(
        `https://api.themoviedb.org/3/search/tv?api_key=YOUR_TMDB_API_KEY&query=${encodeURIComponent(searchTerm)}&language=tr-TR`
      );
      const data = await response.json();
      setSearchResults(data.results);
    } catch (err) {
      setError('Dizi arama sırasında bir hata oluştu.');
      console.error('Search error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAddSeries = async (series) => {
    try {
      const seriesRef = ref(database, 'series');
      const newSeries = {
        title: series.name,
        coverImage: `https://image.tmdb.org/t/p/w500${series.poster_path}`,
        totalSeasons: series.number_of_seasons || 1,
        currentSeason: 1,
        episodesPerSeason: series.episode_run_time?.[0] || 0,
        currentEpisode: 1,
        watchedEpisodes: {
          Beyza: {},
          Mücahit: {}
        },
        createdAt: new Date().toISOString()
      };

      await push(seriesRef, newSeries);
      navigate('/series');
    } catch (err) {
      setError('Dizi eklenirken bir hata oluştu.');
      console.error('Add series error:', err);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-pink-50 py-8">
      <div className="container mx-auto px-4">
        <div className="max-w-2xl mx-auto">
          <h1 className="text-3xl font-bold text-gray-800 mb-8 text-center">
            Dizi Ara
          </h1>

          <form onSubmit={handleSearch} className="mb-8">
            <div className="flex gap-4">
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Dizi adı girin..."
                className="flex-1 px-4 py-2 rounded-lg border border-gray-300 focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
              <button
                type="submit"
                disabled={loading}
                className="px-6 py-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-lg hover:from-purple-600 hover:to-pink-600 focus:outline-none focus:ring-2 focus:ring-purple-500 disabled:opacity-50"
              >
                {loading ? 'Aranıyor...' : 'Ara'}
              </button>
            </div>
          </form>

          {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg mb-4">
              {error}
            </div>
          )}

          <div className="grid gap-6">
            {searchResults.map((series) => (
              <div
                key={series.id}
                className="bg-white rounded-lg shadow-md overflow-hidden"
              >
                <div className="flex">
                  <img
                    src={`https://image.tmdb.org/t/p/w200${series.poster_path}`}
                    alt={series.name}
                    className="w-32 h-48 object-cover"
                  />
                  <div className="p-4 flex-1">
                    <h2 className="text-xl font-semibold text-gray-800 mb-2">
                      {series.name}
                    </h2>
                    <p className="text-gray-600 mb-4">{series.overview}</p>
                    <button
                      onClick={() => handleAddSeries(series)}
                      className="px-4 py-2 bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-lg hover:from-purple-600 hover:to-pink-600 focus:outline-none focus:ring-2 focus:ring-purple-500"
                    >
                      Diziyi Ekle
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default SearchSeries;
